50 | @Command(name = "e2m", description = "Eclipse project to Maven project converter", version = "1.1.0", mixinStandardHelpOptions = true)
51 | public class Main implements Callable<Integer> {
52 | 
53 |     private static final Logger log = AppLogger.get(Main.class);
54 |     private static String e2mVersion;
55 | 
56 |     /** コマンドライン引数のコピー（デバッグ ZIP 用）。 */
57 |     private String[] rawArgs;
58 | 
59 |     @Option(names = {"-g", "--groupId"}, required = false, description = "Maven groupId of the output project")
60 |     private String groupId;
61 | 
62 |     @Option(names = {"-a", "--artifactId"}, required = false, description = "Maven artifactId of the output project")
63 |     private String artifactId;
64 | 
65 |     @Option(names = {"-v", "--artifactVersion"}, required = false, description = "Maven version of the output project (default: 1.0-SNAPSHOT)")
66 |     private String artifactVersion;
67 |     private static final String DEFAULT_ARTIFACT_VERSION = "1.0-SNAPSHOT";
68 | 
69 |     @Option(names = {"--javaTargetVersion"}, required = false, converter = JavaVersionConverter.class,
70 |             description = "Override maven.compiler.target in the generated pom.xml (default: taken from the Eclipse project settings)")
71 |     private JavaVersion javaTargetVersion;
72 | 
73 |     @Option(names = {"--convertToUtf8"}, description = "Convert source files to UTF-8 encoding during copy")
74 |     private boolean convertToUtf8;
75 | 
76 |     @Option(names = {"-e", "--sourceEncoding"}, required = false, description = "Source encoding of the input files (e.g. Shift_JIS). Required when --convertToUtf8 is specified.")
77 |     private String sourceEncoding;
78 | 
79 |     @Option(names = {"--debug"}, description = "Output debug information as e2m_debug_<datetime>.zip in the output directory")
80 |     private boolean debug;
81 | 
