100 |     @Override
101 |     public Integer call() {
102 |         // --debug が指定された場合はファイルログを有効化（outputDir 配下に一時ファイルを作成）
103 |         if (debug) {
104 |             String timestamp = LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd_HHmmss"));
105 |             Path logFilePath = outputDir.toPath().resolve("e2m_debug_" + timestamp + ".log");
106 |             AppLogger.enableDebug(logFilePath);
107 |             log.debug("デバッグモード有効: ログファイル={}", logFilePath);
108 |             log.debug("e2mバージョン={}", e2mVersion);
109 |         }
110 | 
111 |         Path eclipsePath = inputDir.toPath();
112 |         Path mavenPath = null; 
113 | 
114 |         // 1. 引数の確認
115 |         if (!inputDir.isDirectory()) {
116 |             log.error(Messages.get("main.inputDirNotFound", inputDir));
117 |             return 1;
118 |         }
119 |         if (!eclipsePath.resolve(".project").toFile().exists()) {
120 |             log.error(Messages.get("main.notEclipseProject", inputDir));
121 |             return 1;
122 |         }
123 |         if (outputDir.exists() && !outputDir.isDirectory()) {
124 |             log.error(Messages.get("main.outputPathMustBeDirectory", outputDir));
125 |             return 1;
126 |         }
127 |         if (javaTargetVersion != null && javaTargetVersion.isUnknown()) {
128 |             log.error(Messages.get("main.invalidJavaTargetVersion", javaTargetVersion));
129 |             return 1;
130 |         }
131 | 
132 |         try {
133 |             // 2. Eclipseプロジェクト情報をパース
134 |             log.info("");
135 |             log.info(Messages.get("main.step1"));
136 |             EclipseProject eclipseProject = EclipseProjectParser.parse(eclipsePath);
137 |             log.info(Messages.get("main.projectName", eclipseProject.projectName()));
138 |             log.info(Messages.get("main.projectType",
139 |                     eclipseProject.webProject() ? Messages.get("main.projectType.web") : Messages.get("main.projectType.java")));
140 |             log.info(Messages.get("main.javaSourceVersion", eclipseProject.javaSourceVersion()));
141 |             log.info(Messages.get("main.javaTargetVersion", eclipseProject.javaTargetVersion()));
142 |             if (eclipseProject.webProject()) {
143 |                 log.info(Messages.get("main.webVersion", eclipseProject.webVersion()));
144 |             }
145 |             log.info(Messages.get("main.sourceFolders", eclipseProject.sourceFolders()));
146 |             if (eclipseProject.webProject()) {
147 |                 log.info(Messages.get("main.webContentFolder", eclipseProject.webContentRoot()));
148 |             }
149 |             log.info(Messages.get("main.jarCount", eclipseProject.jarFiles().size()));
150 | 
151 |             if (eclipseProject.javaSourceVersion().isUnknown()) {
152 |                 log.error(Messages.get("main.unrecognizedJavaSourceVersion", eclipseProject.javaSourceVersion()));
153 |                 return 1;
154 |             }
155 | 
156 |             log.info("");
157 |             log.info(Messages.get("main.step2"));
158 |             String defaultArtifactId = convertToArtifactId(eclipseProject.projectName());
159 |             if (groupId == null || groupId.isBlank()) {
160 |                 // オプション未指定の場合は対話的に入力を受け付ける
161 |                 try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
162 |                     log.debug("対話的入力モード開始");
163 |                     groupId = promptIfAbsent(reader, "groupId", groupId, null);
164 |                     artifactId = promptIfAbsent(reader, "artifactId", artifactId, defaultArtifactId);
165 |                     artifactVersion = promptIfAbsent(reader, "artifactVersion", artifactVersion, DEFAULT_ARTIFACT_VERSION);
166 |                     log.debug("groupId: {}", groupId);
167 |                     log.debug("artifactId: {}", artifactId);
168 |                     log.debug("version: {}", artifactVersion);
169 |                     // --convertToUtf8 未指定時は対話入力
170 |                     if (!convertToUtf8) {
171 |                         String answer = promptIfAbsent(reader,
172 |                             Messages.get("main.convertToUtf8"), null, "y/N").toLowerCase();
173 |                         convertToUtf8 = ("y".equals(answer) || "yes".equals(answer));
174 |                     }
175 |                     // --convertToUtf8 指定時は sourceEncoding も対話入力
176 |                     if (convertToUtf8) {
177 |                         sourceEncoding = promptIfAbsent(reader,
178 |                             Messages.get("main.sourceEncoding"), sourceEncoding, null);
179 |                         log.debug("sourceEncoding: {}", sourceEncoding);
180 |                     }
181 |                     if (eclipseProject.webProject() && !noLiberty) {
182 |                         String answer = promptIfAbsent(reader,
183 |                             Messages.get("main.addLiberty"), null, "Y/n").toLowerCase();
184 |                         noLiberty = ("n".equals(answer) || "no".equals(answer));
185 |                     }
186 |                     log.debug("noLiberty: {}", noLiberty);
187 |                 }
188 |             } else {
189 |                 // 少なくとも--groupIdが指定されていれば，あとは空ならデフォルトを使用する
190 |                 if (artifactId == null || artifactId.isBlank()) {
191 |                     artifactId = defaultArtifactId;
192 |                 }
193 |                 if (artifactVersion == null || artifactId.isBlank()) {
194 |                     artifactVersion = DEFAULT_ARTIFACT_VERSION;
195 |                 }
196 |                 log.info(Messages.get("main.groupId", groupId));
197 |                 log.info(Messages.get("main.artifactId", artifactId));
198 |                 log.info(Messages.get("main.version", artifactVersion));
199 |                 // --convertToUtf8 指定時は sourceEncoding も対話入力（--groupId 指定時で未指定の場合）
200 |                 if (convertToUtf8 && (sourceEncoding == null || sourceEncoding.isBlank())) {
201 |                     log.debug("対話的入力モード開始");
202 |                     try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
203 |                         sourceEncoding = promptIfAbsent(reader,
204 |                             Messages.get("main.sourceEncoding"), sourceEncoding, null);
205 |                     }
206 |                     log.debug("sourceEncoding: {}", sourceEncoding);
207 |                 }
208 |             }
209 | 
210 |             // --convertToUtf8 指定時の sourceEncoding バリデーション
211 |             Charset srcCharset = null;
212 |             if (convertToUtf8) {
213 |                 try {
214 |                     srcCharset = Charset.forName(sourceEncoding);
215 |                 } catch (Exception e) {
216 |                     log.error(Messages.get("main.invalidSourceEncoding", sourceEncoding));
217 |                     return 1;
218 |                 }
219 |             }
220 | 
221 |             // 出力先は outputDir/artifactId
222 |             mavenPath = outputDir.toPath().resolve(artifactId);
223 |             if (mavenPath.toFile().exists()) {
224 |                 log.error(Messages.get("main.outputDirAlreadyExists", mavenPath));
225 |                 return 1;
226 |             }
227 | 
228 |             log.info("");
229 |             log.info(Messages.get("main.conversionStart"));
230 |             log.info(Messages.get("main.input", eclipsePath.toAbsolutePath()));
231 |             log.info(Messages.get("main.output", mavenPath.toAbsolutePath()));
232 | 
233 |             // 3.(続き) JAR依存関係を解決
234 |             log.info("");
235 |             log.info(Messages.get("main.step3"));
236 |             List<MavenDependency> dependencies = DependencyResolver.resolve(eclipseProject.jarFiles(), eclipsePath);
237 |             long found = dependencies.stream().filter(d -> !"system".equals(d.scope())).count();
238 |             long system = dependencies.stream().filter(d -> "system".equals(d.scope())).count();
239 |             log.info(Messages.get("main.foundDependencies", found));
240 |             log.info(Messages.get("main.systemDependencies", system));
241 | 
242 |             // 4. pom.xml を生成
243 |             log.info("");
244 |             log.info(Messages.get("main.step4"));
245 |             // --javaTargetVersion が指定された場合はソースバージョンと比較してバリデーション
246 |             JavaVersion sourceVer = eclipseProject.javaSourceVersion();
247 |             if (javaTargetVersion != null) {
248 |                 if (!sourceVer.isUnknown() && javaTargetVersion.compareTo(sourceVer) < 0) {
249 |                     log.error(Messages.get("main.javaTargetLowerThanSource",
250 |                             javaTargetVersion, eclipseProject.javaSourceVersion()));
251 |                     return 1;
252 |                 }
253 |             }
254 |             // 実効 javaTargetVersion を確定（--javaTargetVersion 指定 > Eclipseプロジェクト設定）
255 |             JavaVersion effectiveTargetVersion = (javaTargetVersion != null && !javaTargetVersion.isUnknown())
256 |                     ? javaTargetVersion
257 |                     : eclipseProject.javaTargetVersion();
258 |             PomGenerator.generate(eclipseProject, dependencies, groupId, artifactId, artifactVersion,
259 |                     effectiveTargetVersion, convertToUtf8, noLiberty, mavenPath);
260 | 
261 |             // 4.(続き) Liberty 対応: server.xml を生成（webProject かつ --noLiberty 未指定の場合のみ）
262 |             if (!noLiberty && eclipseProject.webProject()) {
263 |                 LibertyServerXmlGenerator.generate(eclipseProject, artifactId, mavenPath);
264 |             }
265 | 
266 |             // 5. ソース・Webコンテンツをコピー
267 |             log.info("");
268 |             log.info(Messages.get("main.step5"));
269 |             if (convertToUtf8) {
270 |                 log.info(Messages.get("main.encodingConversionMode", sourceEncoding));
271 |             }
272 |             ProjectCopier.copy(eclipseProject, dependencies, eclipsePath, mavenPath,
273 |                     convertToUtf8, srcCharset, effectiveTargetVersion);
274 | 
275 |             log.info("");
276 |             log.info(Messages.get("main.conversionComplete"));
277 |             log.info(Messages.get("main.outputDir", mavenPath.toAbsolutePath()));
278 | 
279 |             return 0;
280 | 
281 |         } catch (Exception e) {
282 |             log.error(Messages.get("main.conversionError", e.getMessage()));
283 |             log.debug("スタックトレース:", e);
284 |             return 2;
285 |         } finally {
286 |             // --debug オプション: デバッグ ZIP を生成
287 |             if (debug) try {
288 |                 DebugArchiver.archive(eclipsePath, outputDir.toPath(), mavenPath, rawArgs);
289 |             } catch (IOException e) {
290 |                 e.printStackTrace();
291 |             }
292 |         }
293 |     }
