295 |     /**
296 |      * 引数が null または空の場合にプロンプトを表示して入力を受け付ける。
297 |      * デフォルト値がある場合は "[default]" 形式で表示し、空入力でデフォルト値を採用する。
298 |      *
299 |      * @param reader       入力ストリーム
300 |      * @param name         項目名（表示用）
301 |      * @param value        コマンドライン引数の値（null または空の場合にプロンプト表示）
302 |      * @param defaultValue デフォルト値（null の場合はデフォルトなし）
303 |      * @return 確定した値
304 |      */
305 |     private static String promptIfAbsent(BufferedReader reader, String name,
306 |             String value, String defaultValue) throws Exception {
307 |         if (value != null && !value.isBlank()) {
308 |             return value;
309 |         }
310 |         while (true) {
311 |             if (defaultValue != null) {
312 |                 System.out.print(Messages.get("main.prompt.withDefault", name, defaultValue));
313 |             } else {
314 |                 System.out.print(Messages.get("main.prompt.withoutDefault", name));
315 |             }
316 |             System.out.flush();
317 |             String line = reader.readLine();
318 |             if (line == null) {
319 |                 // EOF（パイプ等）の場合はデフォルト値を使用
320 |                 return defaultValue != null ? defaultValue : "";
321 |             }
322 |             String trimmed = line.trim();
323 |             if (trimmed.isEmpty()) {
324 |                 if (defaultValue != null) {
325 |                     return defaultValue;
326 |                 }
327 |                 // 対話的入力モードでのメッセージは，ロガーを使わず，直接System.outに出力
328 |                 System.out.print(Messages.get("main.prompt.enterValue"));
329 |                 continue;
330 |             }
331 |             return trimmed;
332 |         }
333 |     }
