335 |     // artifactIdとして許可する文字（半角英数字、ハイフン、アンダースコア）以外にマッチする正規表現
336 |     private static final Pattern INVALID_CHARS = Pattern.compile("[^a-z0-9\\-_]");
337 | 
338 |     // キャメルケースの境界（大文字の前）にマッチする正規表現
339 |     private static final Pattern CAMEL_CASE_BOUNDARY = Pattern.compile("(?<=[a-z0-9])(?=[A-Z])");
340 | 
341 |     /**
342 |      * プロジェクト名からMavenのartifactIdとして利用可能な文字列を生成します。
343 |      *
344 |      * @param projectName プロジェクト名
345 |      * @return artifactId用文字列
346 |      */
347 |     public static String convertToArtifactId(String projectName) {
348 |         if (projectName == null || projectName.isBlank()) {
349 |             return "default-artifact";
350 |         }
351 | 
352 |         // 1. パッケージ名が含まれている場合（完全限定名）、最後のクラス名部分だけを抽出
353 |         String simpleName = projectName.substring(projectName.lastIndexOf('.') + 1);
354 | 
355 |         // 2. キャメルケース（OrderManager -> Order-Manager）をハイフン区切りに変換
356 |         String kebabCase = CAMEL_CASE_BOUNDARY.matcher(simpleName).replaceAll("-");
357 | 
358 |         // 3. すべて小文字に変換
359 |         String lowerCase = kebabCase.toLowerCase();
360 | 
361 |         // 4. artifactIdとして使えない文字（日本語や特殊記号など）を完全に除去
362 |         String sanitized = INVALID_CHARS.matcher(lowerCase).replaceAll("");
363 | 
364 |         // 5. 連続したハイフンやアンダースコアを綺麗に整理
365 |         sanitized = sanitized.replaceAll("[-_]{2,}", "-");
366 | 
367 |         // 6. 先頭や末尾にあるハイフン・アンダースコアを除去
368 |         sanitized = sanitized.replaceAll("^[-_]+|[-_]+$", "");
369 | 
370 |         // すべての文字が削られて空になった場合のフォールバック
371 |         return sanitized.isBlank() ? "converted-artifact" : sanitized;
372 |     }
373 | 
374 |     /**
375 |      * picocli 用の {@link JavaVersion} 型変換クラス。
376 |      * 変換に失敗した場合は {@link JavaVersion#UNKNOWN_VERSION} を返す。
377 |      */
378 |     static class JavaVersionConverter implements ITypeConverter<JavaVersion> {
379 |         @Override
380 |         public JavaVersion convert(String value) {
381 |             return JavaVersion.of(value);
382 |         }
383 |     }
384 | }
