     * 変換に失敗した場合は {@link JavaVersion#UNKNOWN_VERSION} を返す。
     */
    static class JavaVersionConverter implements ITypeConverter<JavaVersion> {
        @Override
        public JavaVersion convert(String value) {
            return JavaVersion.of(value);
        }
